const inputs = $input.all().map(i => i.json);
function parseUptime(v) {
  if (v === null || v === undefined) return 0;
  if (typeof v === 'number') return Number.isFinite(v) && v > 0 ? v : 0;
  const s = String(v).trim();
  if (s === '' || s === '0' || s === '0s') return 0;
  let m = s.match(/^(?:(\d+)w)?(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/i);
  if (m && m[0] !== '') {
    const g = i => parseInt(m[i] || '0', 10);
    return (((g(1) * 7 + g(2)) * 24 + g(3)) * 60 + g(4)) * 60 + g(5);
  }
  m = s.match(/^(\d+):(\d{1,2}):(\d{1,2})$/);
  if (m) return (+m[1]) * 3600 + (+m[2]) * 60 + (+m[3]);
  const n = Number(s);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : 0;
