  if (!url) throw new Error('PDF_SERVICE_URL est obligatoire.');
  const base = url.replace(/\/forms\/.*$/, '');
  try {
    await helpers.httpRequest({ method: 'GET', url: base + '/health', timeout: 10000 });
    return;
  } catch (e) { /* repli : sonde directe de l'endpoint */ }
  try {
    await helpers.httpRequest({ method: 'GET', url, timeout: 10000 });
    return;
  } catch (e) {
    const sc = e.statusCode || (e.response && (e.response.statusCode || e.response.status));
