    url: cfg.routerBaseUrl + '/rest/ip/hotspot/user',
    headers: { Authorization: auth, Accept: 'application/json' },
    json: true,
    timeout: 30000,
    skipSslCertificateValidation: (['1', 'true', 'oui'].indexOf(String(($env && $env.ROUTEROS_TLS_INSECURE) || '').toLowerCase()) !== -1) /* Exception labo explicite uniquement, verifie par defaut. */
  });
  const profRes = await this.helpers.httpRequest({
    method: 'GET',
    url: cfg.routerBaseUrl + '/rest/ip/hotspot/user/profile',
    headers: { Authorization: auth, Accept: 'application/json' },
    json: true,
    timeout: 30000,
    skipSslCertificateValidation: (['1', 'true', 'oui'].indexOf(String(($env && $env.ROUTEROS_TLS_INSECURE) || '').toLowerCase()) !== -1) /* Exception labo explicite uniquement, verifie par defaut. */
  });
  const profs = Array.isArray(profRes) ? profRes : (profRes.data || profRes.results || []);
  if (!profs.some(p => String(p.name) === cfg.profile)) throw new Error('Profil hotspot "' + cfg.profile + '" introuvable (creez-le dans /ip/hotspot/user/profile).');
  const users = Array.isArray(response) ? response : (response.data || response.results || []);
  const sameProfile = users.filter(u => String(u.profile || '') === cfg.profile);
  const available = sameProfile.filter(u => !isDisabled(u) && parseUptime(u.uptime) === 0);
  const shouldGenerate = available.length <= cfg.threshold; // Declenchement de 0 au seuil inclus : 0, 49 ou 50 (seuil 50) generent.
  out.push({ json: { ...cfg, existingNames: users.map(u => String(u.name)), stockTotal: sameProfile.length, stockAvailable: available.length, shouldGenerate, checkedAt: new Date().toISOString() } });
