const inputs = $input.all().map(i => i.json);
const alphabet = '23456789abcdefghijkmnpqrstuvwxyz';
const aleatoireCrypto = (n) => { try { var NC = require('crypto'); if (NC && NC.randomBytes) return NC.randomBytes(n); } catch (eCrypto) {} throw new Error('Génération aléatoire sécurisée indisponible : aucun ticket créé.'); }; const rand = len => { const o = aleatoireCrypto(len); let s = ''; for (let i = 0; i < len; i++) s += alphabet[o[i] % alphabet.length]; return s; }; const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); 
// Format Mikhmon : 05-JOURS -> 5j, puis 6 chiffres ; mot de passe = identifiant.
const prefixeDuProfil = (p) => { const m = String(p || '').match(/^0*(\d+)\s*-?\s*([HJSM])/i); return m ? m[1] + m[2].toLowerCase() : ''; };
const chiffres = (n) => { const o = aleatoireCrypto(n); let s = ''; for (let i = 0; i < n; i++) s += '23456789'[o[i] % 8]; return s; };
const dateMikhmon = (d) => String(d.getUTCMonth() + 1).padStart(2, '0') + '.' + String(d.getUTCDate()).padStart(2, '0') + '.' + String(d.getUTCFullYear()).slice(-2);
const COULEURS = { 100: 'bg-100', 200: 'bg-200', 300: 'bg-300', 500: 'bg-500', 700: 'bg-700', 1000: 'bg-1000', 1500: 'bg-1500', 2500: 'bg-2500', 3000: 'bg-3000' };
const JOURS = { 1: '01-JOUR', 3: '03-JOURS', 5: '05-JOURS', 7: '01-SEMAINE', 10: '10-JOURS', 14: '02-SEMAINES', 30: '01-MOIS', 60: '02-MOIS', 90: '03-MOIS' };
const afficherValidite = (v, profil) => { const s = String(v || '').trim().toLowerCase(); let m = s.match(/^(\d+)h$/); if (m) return String(Number(m[1])).padStart(2, '0') + '-HEURES'; m = s.match(/^(\d+)d$/); if (m) return JOURS[Number(m[1])] || String(Number(m[1])).padStart(2, '0') + '-JOURS'; return (s ? s : String(profil || '')).toUpperCase(); };
// Lecture comme Mikhmon : on-login = x,x,prix,validite,prix de vente,...
const lirePrixValidite = (onLogin) => { const c = String(onLogin || '').split(','); const num = (v) => parseInt(String(v == null ? '' : v).replace(/[^0-9]/g, ''), 10) || 0; return { prix: num(c[4]) || num(c[2]), validite: c[3] || '' }; };
const afficherPrix = (n) => n >= 1000 ? String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') : String(n);
// ponytail: lot déduit du runId pour détecter un rejeu sans marque dans le
// commentaire ; 1 chance sur 900 de collision le même jour, le cycle suivant reprend.
const commentaireDuLot = (cleLot) => { const lot = cleLot ? 100 + (require('crypto').createHash('sha256').update(cleLot).digest().readUInt16BE(0) % 900) : 100 + (aleatoireCrypto(2).readUInt16BE(0) % 900); return 'vc-' + lot + '-' + dateMikhmon(new Date()); };
const vendeursDe = (cfg) => (Array.isArray(cfg.vendeursZone) ? cfg.vendeursZone.map(String).filter(Boolean) : []);
const commentairesVendeurs = (cfg, cleLot) => { if (String(cfg.varianteMikhmon || '') !== 'sf-v1') return null; var v = vendeursDe(cfg); if (!v.length) return null; var base = cleLot ? 100 + (require('crypto').createHash('sha256').update(cleLot).digest().readUInt16BE(0) % 900) : 100 + (aleatoireCrypto(2).readUInt16BE(0) % 900); base = Math.min(base, 1000 - v.length); return v.map(function (numero, i) { return { numero: numero, lot: base + i, commentaire: 'vc-' + (base + i) + '-' + dateMikhmon(new Date()) }; }); };
const usedNames = new Set();
for (const c of inputs) for (const n of (c.existingNames || [])) usedNames.add(n);
function uniqueUsername(prefix, len) {
  for (let attempt = 0; attempt < 25; attempt++) {
    const u = (prefix || '') + chiffres(len);
    if (!usedNames.has(u)) { usedNames.add(u); return u; }
  }
