}
const out = [];
const clesVues = new Set();
for (const cfg of inputs) {
  const auth = 'Basic ' + Buffer.from(cfg.routerUser + ':' + cfg.routerPassword).toString('base64');
  const cle = String(cfg.cleIdempotence || '');
  const marqueur = cle ? ('cle:' + cle) : '';
  // Idempotence : un appel rejoue avec la meme cle retrouve les
  // tickets deja crees (commentaire traceur) et n'en recree aucun.
  if (marqueur && !clesVues.has(marqueur)) {
    let existants = [];
    try {
      const deja = await this.helpers.httpRequest({ method: 'GET', url: cfg.routerBaseUrl + '/rest/ip/hotspot/user', headers: { Authorization: auth, Accept: 'application/json' }, json: true, timeout: 30000, skipSslCertificateValidation: (['1', 'true', 'oui'].indexOf(String(($env && $env.ROUTEROS_TLS_INSECURE) || '').toLowerCase()) !== -1) /* Exception labo explicite uniquement, verifie par defaut. */ });
      existants = Array.isArray(deja) ? deja : (deja.data || deja.results || []);
    } catch (e) {
