    }
    if (existants.some(function (u) { const cu = String((u && u.comment) || ''); var cv = commentairesVendeurs(cfg, cle); return cu.indexOf(marqueur) !== -1 || cu === commentaireDuLot(cle) || (cv !== null && cv.some(function (x) { return cu === x.commentaire; })); })) {
      out.push({ json: { ...cfg, tickets: [], generatedAt: new Date().toISOString(), html: '', generatedCount: 0, dejaGenere: true } });
