    const liste = Array.isArray(relu) ? relu : (relu.data || relu.results || []);
    const neuf = function (u) { return String((u && u.profile) || '') === cfg.profile && (u && u.disabled) !== true && String((u && u.disabled) || '').toLowerCase() !== 'true' && ['0s', '00:00:00', ''].indexOf(String((u && u.uptime) || '0s').trim()) !== -1; };
    stockApres = liste.filter(neuf).length;
