const result = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.printnode.com/printjobs', headers: { Authorization: auth, 'Content-Type': 'application/json' }, body: { printerId: cfg.printNodePrinterId, title: 'Tickets Mikhmon ' + cfg.profile, contentType: 'pdf_base64', content: pdf.toString('base64'), source: 'n8n-mikhmon' }, json: true, timeout: 60000 });
return [{ json: { status: 'printed', printNode: result, generatedCount: cfg.generatedCount, profile: cfg.profile } }];

const cfg = $json;
if (!cfg.routerPassword) throw new Error('ROUTEROS_PASSWORD est obligatoire.');
const auth = 'Basic ' + Buffer.from(cfg.routerUser + ':' + cfg.routerPassword).toString('base64');
const response = await this.helpers.httpRequest({ method: 'GET', url: cfg.routerBaseUrl + '/rest/ip/hotspot/user', headers: { Authorization: auth, Accept: 'application/json' }, json: true, timeout: 30000, skipSslCertificateValidation: (['1', 'true', 'oui'].indexOf(String(($env && $env.ROUTEROS_TLS_INSECURE) || '').toLowerCase()) !== -1) });
const users = Array.isArray(response) ? response : (response.data || response.results || []);
const available = users.filter(u => String(u.profile || '') === cfg.profile && String(u.disabled || '').toLowerCase() !== 'true' && ['0s', '0'].includes(String(u.uptime || '0s')));
return [{ json: { ...cfg, stockAvailable: available.length, requestedAt: new Date().toISOString() } }];

const cfg = $json;
const approvalUrl = $execution.resumeUrl;
const approveUrl = approvalUrl + '?approved=true';
const rejectUrl = approvalUrl + '?approved=false';
const text = `🔐 DEMANDE D'APPROBATION

Profil: ${cfg.profile}
Quantité demandée: ${cfg.quantity}
Stock actuel: ${cfg.stockAvailable}
Seuil: ${cfg.threshold}
Canal: ${cfg.deliveryChannel}
Destinataire: ${cfg.recipient}

Utilisez un bouton ci-dessous pour approuver ou refuser.`;
return [{ json: { ...cfg, approvalUrl, approveUrl, rejectUrl, approvalMessage: text } }];

const approval = $json.query ?? $json.body ?? $json;
const approved = approval.approved === true || String(approval.approved).toLowerCase() === 'true' || String(approval.action).toLowerCase() === 'approve';
return [{ json: { ...$json, approved, approvalDecisionAt: new Date().toISOString(), approvalComment: String(approval.comment || '') } }];

const env = (name, fallback = '') => String(($env && $env[name]) || fallback);
const mode = env('MIKHMON_WEEKLY_MODE', 'disabled').toLowerCase();
if (mode !== 'weekly_prompt' && mode !== 'weekly_auto') return [];
const now = new Date();
const jours = env('MIKHMON_WEEKLY_DAYS', '1').split(',').map(v => Number(v.trim())).filter(v => Number.isInteger(v) && v >= 0 && v <= 6);
const heure = env('MIKHMON_WEEKLY_TIME', '09:00').match(/^(\d{2}):(\d{2})$/);
if (!jours.length || !heure) throw new Error('Planification invalide : MIKHMON_WEEKLY_DAYS doit contenir 0..6 et MIKHMON_WEEKLY_TIME HH:mm.');
const minuteActuelle = now.getUTCHours() * 60 + now.getUTCMinutes();
const minuteCible = Number(heure[1]) * 60 + Number(heure[2]);
if (jours.indexOf(now.getUTCDay()) === -1 || minuteActuelle < minuteCible || minuteActuelle >= minuteCible + 15) return [];
const jour = now.toISOString().slice(0, 10);
const profil = env('MIKHMON_WEEKLY_PROFILE', env('MIKHMON_PROFILE', 'default'));
const quantity = Math.max(1, Math.min(500, Number(env('MIKHMON_WEEKLY_QUANTITY', env('TICKET_QUANTITY', '50'))) || 50));
const deliveryChannel = env('MIKHMON_WEEKLY_CHANNEL', env('DELIVERY_CHANNEL', 'telegram')).toLowerCase();
const recipient = env('MIKHMON_WEEKLY_RECIPIENT', env('DELIVERY_RECIPIENT', ''));
const approvalRecipient = env('MIKHMON_WEEKLY_APPROVAL_RECIPIENT', recipient);
const appUrl = env('APP_URL', '').replace(/\/$/, '');
const runId = 'weekly-' + jour + '-' + String(profil).replace(/[^a-zA-Z0-9_-]/g, '_');
return [{ json: {
  route: mode === 'weekly_prompt' ? 'prompt' : 'auto',
  runId, cleIdempotence: runId, tenantId: env('TENANT_ID', 'defaut'), userId: env('WEEKLY_USER_ID', ''),
  routerBaseUrl: env('ROUTEROS_BASE_URL', ''), routerUser: env('ROUTEROS_USER', 'n8n-vouchers'), routerPassword: env('ROUTEROS_PASSWORD', ''),
  hotspotServer: env('MIKHMON_HOTSPOT_SERVER', 'all'), profile: profil, quantity, threshold: Number(env('TICKET_THRESHOLD', '50')) || 50,
  deliveryChannel, recipient, approvalRecipient, telegramBotToken: env('TELEGRAM_BOT_TOKEN', ''),
  pdfServiceUrl: env('PDF_SERVICE_URL', 'http://gotenberg:3000/forms/chromium/convert/html'),
  whatsappWebhookUrl: env('WHATSAPP_WEBHOOK_URL', ''), printNodeApiKey: env('PRINTNODE_API_KEY', ''), printNodePrinterId: Number(env('PRINTNODE_PRINTER_ID', '0')) || 0,
  callbackUrl: appUrl ? appUrl + '/api/internal/n8n/callback' : '', forcerGeneration: mode === 'weekly_auto',
  weeklyMode: mode, weeklyDays: jours, weeklyTime: env('MIKHMON_WEEKLY_TIME', '09:00'), scheduledAt: now.toISOString()
} }];
